// Warning this technique doesn't work well on crappy LCD panels!
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
// Adjust scroll speed
#define SPEED (1.0/400.0)
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
// 1/frames for a full static cleaner pass
#define CLEAN (1.0/512.0)
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
// 0.0 = no chroma safety, 1.0 = full chroma safety (in possible ghost)
#define CHROMA 1.0
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
// 1.0 = full brightness, <1.0 gets darker but has less ghosting
#define BRIGHT 0.875
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
// 1 = test simple linear gradient, 0 = test scrolling image
#define BAD_PANEL_TEST 0
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
