//                                   ABOUT
//-------------------------------------::---------------------------------------
// Fixed Black Frame Insertion frame rate doubler
// Works using the energy redistribution logic from Timothy Lottes
// Mixed with a modified CRT beam simulation logic from Mark Rejhon
//-------------------------------------::---------------------------------------
// It uses rolling BFI
// The rolling BFI phase is driven by a sine wave
// Then modified by the ANTI-SAH (anti-scan-and-hold) logic
// Which pushes the transition away from the 0.5 SAH mid-point
// To better maintain motion clarity
// This low frequency scrolling BFI phase change kills static charge buildup
//=====================================||=======================================
//|||||||||||||||||||||||||||||||||||||::|||||||||||||||||||||||||||||||||||||||
//=====================================||=======================================
//                                  CONTROLS
//=====================================||=======================================
// Pushes scanline frame phase away from the mid-point which is scan-and-hold
//  0 ... off, narrow BFI region, fastest 
//  3 ... not narrow BFI region
//  N ... the larger the tighter the transition
#ifndef BF2_ANTI_SAH
 #define BF2_ANTI_SAH 8
#endif
//-------------------------------------::---------------------------------------
// Control over the ghost de-chroma
//  0 ... [fastest] Force disable .. temporal energy spill will change RGB ratio
//  1 ... [slower ] Force enable ... temporal energy spill will not change ratio
//  2 ... [slowest] User setting 'g' is used in Bf2() [default]
#ifndef BF2_GHOST_DECHROMA
 #define BF2_GHOST_DECHROMA 2
#endif
//|||||||||||||||||||||||||||||||||||||::|||||||||||||||||||||||||||||||||||||||
//=====================================||=======================================
//                                 PORTABILITY
//=====================================||=======================================
#ifdef BF2_GLSL
#endif
//=====================================||=======================================
#ifdef BF2_HLSL
#endif
//=====================================||=======================================
#ifdef BF2_SHADERTOY
 #define F1 float
 #define F2 vec2
 #define F3 vec3
 #define F4 vec4
 #define H1 float
 #define H2 vec2
 #define H3 vec3
 #define H4 vec4
 #define I1 uint
 #define P1 bool
 #define P3 bvec3
//-------------------------------------::---------------------------------------
 // This offers a place for a platform to optimize using intrinsics 
 #define VAddF1(a,b) ((a)+(b))
 #define VAddH1(a,b) ((a)+(b))
 #define VAddH3(a,b) ((a)+(b))
 #define VClampH3(a,b,c) clamp(a,b,c)
 #define VCmpGtH3(a,b) P3((a).x>(b).x,(a).y>(b).y,(a).z>(b).z)
 // Note this is scaled by 2pi (matches AMD's native opcode)
 #define VCosF1(a) cos((a)*F1(2.0*3.14159))
 #define VCvtF1I1(a) F1(a)
 #define VCvtH1F1(a) H1(a)
 #define VFmaF1(a,b,c) ((a)*(b)+(c))
 #define VFmaH1_F1F1F1(a,b,c) H1((a)*(b)+(c))
 #define VFmaH3(a,b,c) ((a)*(b)+(c))
 #define VFractF1(a) fract(a)
 #define VMax3H1(a,b,c) max(a,max(b,c))
 #define VMulF1(a,b) ((a)*(b))
 #define VMulH3(a,b) ((a)*(b))
 #define VPowF1(a,b) pow(a,b)
 #define VPowH3(a,b) pow(a,b)
 #define VRcpF1(a) (F1(1.0)/(a))
 #define VRcpH1(a) (H1(1.0)/(a))
 #define VSatF1(a) clamp(a,F1(0.0),F1(1.0))
 #define VSatH1(a) clamp(a,H1(0.0),H1(1.0))
 #define VSatH3(a) clamp(a,H3(0.0),H3(1.0))
 #define VSelH3(a,b,p) mix(a,b,p)
#endif
//|||||||||||||||||||||||||||||||||||||::|||||||||||||||||||||||||||||||||||||||
//=====================================||=======================================
//                  SUPPORTING FAST COLOR CONVERSION LOGIC
//-------------------------------------::---------------------------------------
// Branch-free
// Most HW lacks the sRGB imageStore() so it often must be done in SW
//=====================================||=======================================
H3 Bf2LinToSrgbH3(H3 c){H3 j=H3(0.0031308*12.92,12.92,1.0/2.4);
 H2 k=H2(1.055,-0.055);
 return VClampH3(H3(j.x),
  VMulH3(c,H3(j.y)),VFmaH3(VPowH3(c,H3(j.z)),H3(k.x),H3(k.y)));}
//-------------------------------------::---------------------------------------
// This shouldn't be used (use the HW decode instead)
H3 Bf2SrgbToLinH3(H3 c){H3 j=H3(0.04045,1.0/12.92,2.4);
 H2 k=H2(1.0/1.055,0.055/1.055);
 return VSelH3(VMulH3(c,H3(j.y)),VPowH3(VFmaH3(c,H3(k.x),H3(k.y)),H3(j.z)),
  VCmpGtH3(c,H3(j.x)));}
//|||||||||||||||||||||||||||||||||||||::|||||||||||||||||||||||||||||||||||||||
//=====================================||=======================================
//                                    ENTRY
//=====================================||=======================================
void Bf2(
out H3 c0, // Even frame output color linear {0 to 1}
out H3 c1, // Odd  frame output color linear {0 to 1}
H3 c,      // Input linear color {0 to 1}
I1 f,      // Frame counter
F1 s,      // Scroll speed for cleaner (1/framesPerFullScroll)
H1 b,      // Brightness {2:full, <2:darker but less possible ghosting}
H2 g,      // Ghost dechroma {0:off, 1:keep consistent chroma} in 'x', 'y=1-x'
F1 y){     // Scanline position {0 to 1}
//-------------------------------------::---------------------------------------
 // Compute phase {0:even, 1:odd} for the scanline
 H2 pp;
 // Start with a basic sine wave
 F1 q=VFractF1(VFmaF1(y,F1(0.5),VMulF1(VCvtF1I1(f),s)));
 q=VSatF1(VFmaF1(VCosF1(q),F1(0.5),F1(0.5)));
//-------------------------------------::---------------------------------------
 #if BF2_ANTI_SAH
  // Quicken the speed away from the scan-and-hold 0.5 mid-point 
  // Smoothstep ref: https://iquilezles.org/articles/smoothsteps/
  // 3rd power
  #if (BF2_ANTI_SAH==3)
   F1 qR=VFmaF1(q,F1(3.0),F1(-3.0));
      qR=VFmaF1(q,qR,     F1( 1.0));
      qR=VRcpF1(qR);
   pp.x=VSatH1(VFmaH1_F1F1F1(q,VMulF1(VMulF1(q,q),qR),F1(0.0)));
  #endif
  // 4th power
  #if (BF2_ANTI_SAH==4)
   F1 qR=VFmaF1(q,F1(2.0),F1(-4.0));
      qR=VFmaF1(q,qR,     F1( 6.0));
      qR=VFmaF1(q,qR,     F1(-4.0));
      qR=VFmaF1(q,qR,     F1( 1.0));
      qR=VRcpF1(qR);
   F1 qq=VMulF1(q,q);
   pp.x=VSatH1(VFmaH1_F1F1F1(VMulF1(qq,qq),qR,F1(0.0)));
  #endif
  // 5th power
  #if (BF2_ANTI_SAH==5)
   F1 qR=VFmaF1(q,F1(5.0),F1(-10.0));
      qR=VFmaF1(q,qR,     F1( 10.0));
      qR=VFmaF1(q,qR,     F1( -5.0));
      qR=VFmaF1(q,qR,     F1(  1.0));
      qR=VRcpF1(qR);
   F1 qq=VMulF1(q,q);
   pp.x=VSatH1(VFmaH1_F1F1F1(VMulF1(q,VMulF1(qq,qq)),qR,F1(0.0)));
  #endif
  // 6th power
  #if (BF2_ANTI_SAH==6)
   F1 qR=VFmaF1(q,F1(2.0),F1( -6.0));
      qR=VFmaF1(q,qR,     F1( 15.0));
      qR=VFmaF1(q,qR,     F1(-20.0));
      qR=VFmaF1(q,qR,     F1( 15.0));
      qR=VFmaF1(q,qR,     F1( -6.0));
      qR=VFmaF1(q,qR,     F1(  1.0));
      qR=VRcpF1(qR);
   F1 qq=VMulF1(q,q);
   pp.x=VSatH1(VFmaH1_F1F1F1(VMulF1(qq,VMulF1(qq,qq)),qR,F1(0.0)));
  #endif
  // Nth power
  #if (BF2_ANTI_SAH>6)
   F1 qq=VPowF1(q,F1(BF2_ANTI_SAH));
   F1 qR=VRcpF1(VAddF1(qq,VPowF1(VAddF1(F1(1.0),-q),F1(BF2_ANTI_SAH))));
   pp.x=VSatH1(VFmaH1_F1F1F1(qq,qR,F1(0.0)));
  #endif
 #else
  pp.x=VCvtH1F1(q);
 #endif
//-------------------------------------::---------------------------------------
 // Finish for lerp later
 pp.y=VAddH1(H1(1.0),-pp.x);
//-------------------------------------::---------------------------------------
 // Compute maximum BFI, starting with all energy in c0
 c0=VMulH3(c,H3(b));
//-------------------------------------::---------------------------------------
 // Compute maximum BFI, starting with all energy in c0
 // Maximum of all channels
 H1 m=VMax3H1(c.r,c.g,c.b);
 // Compute color ratio (all zero return zero)
 // Note {rcp(0)=INF, INF*0=NaN, saturate(NaN)=0}
 H3 r=VSatH3(VMulH3(c,H3(VRcpH1(m))));
//-------------------------------------::---------------------------------------
 // Compute two possible c0 options
 // The first {a0} is the maximum possible
 H3 a0=VSatH3(VMulH3(c,H3(b)));
 // The second {a1} is what is possible given keeping same chroma as source
 H3 a1=VMulH3(r,H3(VMax3H1(a0.r,a0.g,a0.b)));
//-------------------------------------::---------------------------------------
 // Make 'd' as maximum display amount for 'c0'
 // First two are fast paths that will rely on dead-code removal
 #if (BF2_GHOST_DECHROMA==0)
  H3 d=a0;
 #endif
 #if (BF2_GHOST_DECHROMA==1)
  H3 d=a1;
 #endif
 #if (BF2_GHOST_DECHROMA==2)
  // Blend between the two depending on user setting for display amount
  H3 d=VFmaH3(a0,H3(g.y),VMulH3(a1,H3(g.x)));
 #endif
//-------------------------------------::---------------------------------------
 // Add any remaining signal back to c1
 c1=VAddH3(c0,-d);
//-------------------------------------::---------------------------------------
 // Blend between the options
 c0=VFmaH3(d,H3(pp.x),VMulH3(c1,H3(pp.y))); 
 c1=VFmaH3(d,H3(pp.y),VMulH3(c1,H3(pp.x)));}






// . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .
//. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
//                              SHADERTOY ENTRY
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
void mainImage(out F4 fragColor,in F2 fragCoord){
 // Shadertoy is OpenGL ES reversed Y (puke)
 F1 y=1.0-(fragCoord.y/iResolution.y);
 // Get the nearest timestamp in units of input frame count
 F1 t=F1(iFrame>>1);
 // Compute the sampling position
 F2 uv;
 uv=fragCoord.xy/iResolution.xy;
 // The right/left split
 P1 bf2=uv.x<0.5;
 // Move it
 uv.x+=t*F1(SPEED)*F1(2.0);
 // Sample then put into linear
 H3 c=H3(textureLod(iChannel0,uv,0.0).rgb);
 // Put into linear
 // This should be done by the texture read for sRGB
 // But shadertoy don't have that ...
 c.rgb=Bf2SrgbToLinH3(c.rgb);
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
 #if BAD_PANEL_TEST 
  // Shows a simple linear gradient
  c.rgb=H3(0.0,1.0-y,0.0);
 #endif
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
 // Run filter
 H3 c0,c1;
 // Note the bright input is scaled by 2
 Bf2(c0,c1,c,I1(iFrame>>1),F1(CLEAN),H1(2.0*BRIGHT),H2(CHROMA,1.0-CHROMA),y);
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
 // Select the correct output 
 // A real engine would just present both {c0,c1}
 // This shader toy just recomputes then selects the right output
 if(bf2)c=(iFrame&1)==0?c0:c1;else c*=H3(BRIGHT);
 // Convert back to sRGB 
 c.rgb=Bf2LinToSrgbH3(c.rgb);
 fragColor=F4(c.r,c.g,c.b,1.0);}
